<?php $naslovStranice='Vozila';require __DIR__.'/../delovi/zaglavlje.php';?><main class="stranica vozila-index-stranica"><div class="breadcrumb"><a href="index.php?stranica=pocetna">Početna</a><span>›</span><strong>Vozila</strong></div><section class="novo-hero vozilo-lista-hero"><div><span class="eyebrow">ŠIFARNIK VOZILA</span><h1>Vozila</h1><p>Pregled voznog parka, tehničkih podataka i raspoloživosti.</p></div><?php if(Sesija::jeAdmin()):?><a class="dugme" href="index.php?stranica=vozilo-dodaj">+ Dodaj vozilo</a><?php endif;?></section><?php if($poruka):?><div class="<?=($poruka['tip']??'')==='greska'?'greska':'poruka'?>"><?=htmlspecialchars($poruka['tekst'])?></div><?php endif;?><section class="panel"><form method="get" class="filter-forma vozilo-filter-forma"><input type="hidden" name="stranica" value="vozila"><input class="filter-input" type="search" name="filter" value="<?=htmlspecialchars($filter)?>" placeholder="Marka, model, registracija ili kategorija"><select class="filter-input" name="status"><option value="">Svi statusi</option><?php foreach(['Slobodno','Iznajmljeno','Servis','Nedostupno'] as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button>Pretraži</button><a class="dugme dugme-sekundarno" href="index.php?stranica=vozila">Očisti</a></form><div class="sekcija-zaglavlje"><span class="broj-rezultata"><?=$ukupno?> vozila</span></div><div class="vozila-upravljanje-grid"><?php foreach($redovi as $v):?><article class="vozilo-upravljanje-kartica"><div class="vozilo-upravljanje-vrh"><span class="vozilo-velika-ikona">🚘</span><span class="status status-<?=strtolower($v['Status'])?>"><?=htmlspecialchars($v['Status'])?></span></div><div class="vozilo-upravljanje-podaci"><span class="sekcija-broj"><?=htmlspecialchars($v['Kategorija']??'Nije uneto')?> · <?=htmlspecialchars((string)($v['Godiste']??'—'))?></span><h3><?=htmlspecialchars($v['Marka'].' '.$v['Model'])?></h3><span class="registracija"><?=htmlspecialchars($v['Registracija'])?></span><small><?=htmlspecialchars($v['Gorivo']??'Nije uneto')?> · <?=htmlspecialchars($v['Menjac']??'Nije uneto')?> · <?=htmlspecialchars((string)($v['BrojSedista']??'—'))?> sedišta · <?=number_format((int)($v['Kilometraza']??0),0,',','.')?> km</small></div><div class="vozilo-upravljanje-cena"><span>Cena po danu</span><strong><?=number_format((float)$v['CenaPoDanu'],2,',','.')?> RSD</strong></div><?php if(Sesija::jeAdmin()):?><div class="vozilo-upravljanje-akcije"><a class="dugme dugme-sekundarno" href="index.php?stranica=vozilo-izmeni&id=<?=$v['ID']?>">Izmeni</a><form method="post" action="index.php?stranica=vozilo-obrisi" onsubmit="return confirm('Obrisati vozilo?')"><input type="hidden" name="id" value="<?=$v['ID']?>"><button class="dugme-opasno">Obriši</button></form></div><?php endif;?></article><?php endforeach;?></div><?php if($brojStr>1):?><nav class="paginacija"><?php for($i=1;$i<=$brojStr;$i++):?><a class="<?=$i===$str?'aktivna':''?>" href="?stranica=vozila&filter=<?=urlencode($filter)?>&status=<?=urlencode($status)?>&str=<?=$i?>"><?=$i?></a><?php endfor;?></nav><?php endif;?></section></main><?php require __DIR__.'/../delovi/podnozje.php';?>